from pathlib import Path
import html
P=Path
E=html.escape
COMPONENTS=[
('argocd-server','Deployment','The front desk: serves the browser UI and CLI/API, authenticates users, enforces Argo RBAC, and accepts management requests.','Needed for our UI/CLI lesson. Auto-reconciliation is performed by the application-controller.'),
('argocd-repo-server','Deployment','The Git reader and renderer: fetches the selected revision and returns desired Kubernetes manifests. It reads raw YAML here; it renders Helm charts in the optional exercise.','Needed to obtain desired manifests. It does not apply the workload to the cluster.'),
('argocd-application-controller','StatefulSet','The reconciler: watches Application objects and live resources, compares desired/live state, applies sync operations, and evaluates resource health.','Needed for sync and self-healing. In this chart it is a StatefulSet with a stable pod name; that does not imply a data PVC exists.'),
('argocd-redis','Deployment','The shared cache: speeds access to generated manifests and application/cluster state.','Present in this installation. Git and Kubernetes API objects remain the durable desired/configuration sources; Redis is not your Git repository.'),
('argocd-applicationset-controller','Deployment','The Application generator: creates or updates Application objects from an ApplicationSet template and generator.','Installed by this chart but unused by our one-Application demo. It does not directly replace the application-controller or deploy pods.'),
('argocd-dex-server','Disabled in our values','An optional identity broker for configured single sign-on integrations. Some deployments use a direct OIDC provider instead.','Not needed for this lab: admin login is handled by argocd-server.'),
('argocd-notifications-controller','Disabled in our values','An optional notifier: sends configured messages when Application events meet configured triggers.','Not needed for deployment or self-healing. No alert destination is configured here.')]
SERVICES=[
('argocd-server','80 and 443 → pod 8080','Browser and CLI/API access. Our helper maps localhost:8090 to Service port 80. Both Service ports target 8080 in this chart; server.insecure=true makes this lab HTTP even though one port is named https.'),
('argocd-repo-server','8081 → pod 8081','Internal gRPC endpoint used to request repository operations and generated manifests. Do not use it as the student browser URL.'),
('argocd-redis','6379 → pod 6379','Internal cache endpoint for Argo components. Keep it internal.'),
('argocd-applicationset-controller','7000 → pod 7000','ApplicationSet webhook receiver. It is not the Argo UI and is not used by the beginner demo.'),
('argocd-application-controller','No Service in this lab','Expected: the controller initiates connections to repo-server, Redis and the Kubernetes API. A component does not need its own inbound Service to operate.')]
FLOW=[
'You apply the Application object. Kubernetes stores that custom resource in its API; it contains the Git URL, main branch, manifest folder, destination and policy.',
'The application-controller sees that Application and requests its desired manifests from repo-server over the internal repo-server Service.',
'Repo-server fetches the selected Git revision and reads the YAML in gitops/demo/manifests. In the Helm exercise it renders the chart. It returns the desired objects; Redis provides caching alongside these operations.',
'The controller compares those objects with live Kubernetes resources. A Git change from replicas 2 to 3 produces a difference. Polling or a configured webhook can cause a new comparison; this lab uses polling.',
'Because automated.enabled is true, the controller applies the desired Deployment through the Kubernetes API. It does not need a human to click Sync or keep the UI open.',
'Kubernetes Deployment/ReplicaSet controllers create the required Pod objects; the scheduler places them and kubelets start containers. Argo observes their readiness and health.',
'The Application status and Git revision are exposed through argocd-server. The browser resource tree and CLI report Synced and Healthy when the required conditions are satisfied.'
]
QUESTIONS=[
('Which component actually reconciles an Application?','argocd-application-controller. The API server accepts user/API requests; repo-server supplies desired manifests.'),
('Does repo-server directly deploy pods?','No. It fetches Git and produces manifests. The application-controller applies desired resources through the Kubernetes API; Kubernetes controllers create and manage pods.'),
('Why is there no application-controller Service?','This installation does not need clients to connect to it. It watches the Kubernetes API and makes outbound calls to its dependencies. Optional metrics Services may exist in other chart configurations.'),
('Why is port 443 not proof of HTTPS here?','Service port numbers and names do not enable encryption. Both ports target the server container port, and the lab explicitly enables HTTP with server.insecure=true.'),
('Will closing the browser stop reconciliation?','No. The browser is a client. The application-controller keeps reconciling while its required dependencies remain available.'),
('What happens if repo-server cannot reach Git?','New comparisons or manifest generation can fail. Inspect the Application conditions and repo-server logs. Previously running NGINX pods can keep serving traffic; new desired-state delivery is affected.'),
('Is Redis the source of truth?','No. It is a cache. Desired manifests are in Git; Application/configuration objects and live resource state are stored through Kubernetes. Redis is not an authoritative replacement for those sources.'),
('Application versus ApplicationSet?','An Application describes one deployment source/destination and policy. An ApplicationSet generates multiple Applications. Each generated Application is reconciled by the application-controller.'),
('Do Dex and notifications need to run for this demo?','No. They are explicitly disabled. Local admin authentication works through argocd-server, and deployment does not require notification delivery.'),
('What is the difference between a component, a pod and a Service?','A component is a functional part of Argo CD. A pod runs its process. A Kubernetes Service gives selected pods a stable network endpoint. They are related, but there is no rule that each component must have exactly one Service.')]
COMMANDS=[
('Find the components and Services','kubectl get deployment,statefulset,pods,svc -n argocd'),
('Inspect Service selectors, ports and ready endpoints','kubectl describe svc argocd-server -n argocd\nkubectl describe svc argocd-repo-server -n argocd\nkubectl get endpointslices -n argocd'),
('Read the three main component logs','kubectl logs -n argocd deployment/argocd-server --tail=20\nkubectl logs -n argocd deployment/argocd-repo-server --tail=20\nkubectl logs -n argocd statefulset/argocd-application-controller --tail=20'),
('Follow the outcome in the destination namespace','kubectl get application demo-nginx -n argocd\nkubectl get deployment,replicaset,pods,svc -n argocd-demo -L demo-version')]
SOURCES=[('Argo architecture','https://argo-cd.readthedocs.io/en/stable/operator-manual/architecture/'),('Caching and availability','https://argo-cd.readthedocs.io/en/stable/operator-manual/high_availability/'),('ApplicationSet integration','https://argo-cd.readthedocs.io/en/stable/operator-manual/applicationset/Argo-CD-Integration/'),('SSO and Dex','https://argo-cd.readthedocs.io/en/stable/operator-manual/user-management/'),('Notifications','https://argo-cd.readthedocs.io/en/stable/operator-manual/notifications/')]

def build_component_section():
    svg='''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1100 750" role="img"><title>Argo CD components and internal Services</title><desc>The browser and CLI reach argocd-server. The application-controller requests desired manifests from repo-server, which reads Git. The controller watches and updates the Kubernetes API; Kubernetes runs application pods. Redis is a supporting cache. ApplicationSet creates Application objects. Dex and notifications are optional and disabled.</desc><defs><marker id="a" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><path d="M0 0 L9 3 L0 6" fill="none" stroke="#287b7b"/></marker></defs><style>text{font:16px system-ui;fill:#203a42}.b{fill:#fff;stroke:#96bdb4;stroke-width:2}.l{fill:none;stroke:#287b7b;stroke-width:2;marker-end:url(#a)}.support{fill:none;stroke:#a67b43;stroke-width:2;stroke-dasharray:6 5}.optional{fill:#fff5e4;stroke:#c9aa76;stroke-width:2}</style><rect width="1100" height="750" rx="20" fill="#eef6f0"/><text x="25" y="35">ARGO CD COMPONENTS • solid arrows show requests / updates; dashed lines show cache support</text><rect class="b" x="25" y="65" width="300" height="80" rx="12"/><text x="42" y="96">Browser / CLI</text><text x="42" y="125">localhost:8090 or playground URL</text><path class="l" d="M325 105 H385"/><rect class="b" x="390" y="65" width="320" height="80" rx="12"/><text x="408" y="96">argocd-server Service :80</text><text x="408" y="125">server pod :8080 • UI / API / auth</text><path class="l" d="M710 105 H780"/><rect class="b" x="785" y="65" width="285" height="80" rx="12"/><text x="802" y="96">Kubernetes API</text><text x="802" y="125">Application CR + live resources</text><rect class="b" x="25" y="225" width="260" height="85" rx="12"/><text x="42" y="256">Git repository</text><text x="42" y="285">main / desired YAML or Helm</text><path class="l" d="M335 267 H290"/><rect class="b" x="340" y="225" width="300" height="85" rx="12"/><text x="357" y="256">repo-server Service :8081</text><text x="357" y="285">Fetch Git + generate manifests</text><path class="l" d="M700 267 H645"/><text x="640" y="330">request / return desired manifests</text><rect class="b" x="705" y="225" width="365" height="85" rx="12"/><text x="722" y="255">application-controller StatefulSet</text><text x="722" y="283">Compare → sync → health • no Service</text><path class="l" d="M927 225 V150"/><text x="940" y="190">watch / apply</text><rect class="b" x="340" y="390" width="300" height="80" rx="12"/><text x="357" y="422">Redis Service :6379</text><text x="357" y="451">Shared cache, not Git storage</text><path class="support" d="M490 310 V390"/><path class="support" d="M550 145 V185 H665 V430 H640"/><path class="support" d="M705 285 H680 V430 H640"/><rect class="b" x="705" y="390" width="365" height="100" rx="12"/><text x="722" y="421">Kubernetes runs the workload</text><text x="722" y="450">Deployment → ReplicaSet → Pods</text><text x="722" y="478">demo-nginx Service → 2 / 3 pods</text><path class="l" d="M1070 125 H1085 V435 H1075"/><rect class="optional" x="25" y="540" width="510" height="95" rx="12"/><text x="42" y="570">ApplicationSet controller • installed, unused here</text><text x="42" y="598">Generates Application objects, not workload pods</text><text x="42" y="623">Service :7000 is its webhook receiver</text><rect class="optional" x="570" y="540" width="500" height="95" rx="12"/><text x="587" y="571">Disabled in this lab</text><text x="587" y="599">Dex: optional SSO identity broker</text><text x="587" y="623">Notifications: optional event messages</text><text x="25" y="684">The API server shows status; repo-server reads Git; application-controller reconciles.</text><text x="25" y="718">Argo manages configuration. NGINX application traffic does not pass through these Argo components.</text></svg>'''
    P('docs/argocd-components.svg').write_text(svg,encoding='utf-8',newline='\n')
    out=['<section id="components"><span class="number">AFTER INSTALL / UNDERSTAND THE COMPONENTS</span><h2>What did Argo CD install, and how does it work?</h2><p>Think of three main jobs: <strong>argocd-server is the front desk, repo-server reads Git, and application-controller does the reconciliation.</strong> Redis supports them with caching. Keep the eight demo steps unchanged; this section explains what you see after step 1.</p><img src="docs/argocd-components.svg" alt="Argo component diagram showing UI/API, repo-server, controller, Git, Kubernetes API, Redis and optional components."><h3>Component, pod and Service are different things</h3><p>A component is a job in the system. A pod runs the process for that job. A Service supplies a stable endpoint for selected pods. The current lab has five running component workloads but only four Services; the controller does not need an inbound Service.</p><h3>Components in this exact lab</h3><table><tr><th>Component</th><th>Kubernetes workload</th><th>What it does</th><th>Needed here?</th></tr>']
    for row in COMPONENTS:out.append('<tr>'+''.join('<td>'+E(cell)+'</td>' for cell in row)+'</tr>')
    out.append('</table><h3>Which Service should I connect to?</h3><p>These names and ports were checked against the running pinned chart. All installed Services below are ClusterIP. Other chart settings may add metrics Services or change names/ports.</p><table><tr><th>Service</th><th>Service → pod port</th><th>Purpose</th></tr>')
    for row in SERVICES:out.append('<tr>'+''.join('<td>'+E(cell)+'</td>' for cell in row)+'</tr>')
    out.append('</table><p class="note"><strong>Only argocd-server is your UI/CLI entry point.</strong> The repo-server, Redis and ApplicationSet webhook ports are internal component endpoints. Port 443 being present does not make this local HTTP lab an HTTPS deployment.</p><h3>Follow one change: Git replicas 2 → 3</h3><ol>')
    out += ['<li>'+E(step)+'</li>' for step in FLOW]
    out.append('</ol><p><strong>Self-healing follows the same comparison path:</strong> when a live edit changes replicas to 1 but Git still says 2, the controller restores 2. Closing the browser does not stop the controller. A running NGINX pod also does not stop merely because an Argo UI connection is closed.</p><h3>Inspect the components yourself</h3>')
    for title,cmd in COMMANDS:out.append('<h3>'+E(title)+'</h3><div class="code"><button type="button">Copy</button><pre><code>'+E(cmd)+'</code></pre></div>')
    out.append('<p>A short-lived <code>argocd-redis-secret-init</code> Job may appear Completed during Helm installation. It is chart initialization, not a fifth Service or a permanently running application component. Missing Dex/notification pods are expected because both are disabled.</p><h3>If something stops working, where do I look?</h3><table><tr><th>Symptom</th><th>First place to inspect</th></tr><tr><td>UI / CLI cannot connect</td><td>Port-forward, argocd-server Service endpoints and server logs.</td></tr><tr><td>Repository fetch or manifest error</td><td>Application conditions, repository URL/revision/path/credentials, repo-server logs.</td></tr><tr><td>Desired state is known but sync does not progress</td><td>Sync policy, controller logs, Kubernetes permissions/admission and operation errors.</td></tr><tr><td>Cache connection errors</td><td>Redis pod, Service endpoints and logs from affected components.</td></tr><tr><td>Application Synced but pods unhealthy</td><td>Destination Deployment, pod readiness, events, image pulls and resources.</td></tr></table><h3>Component interview questions and answers</h3>')
    for question,answer in QUESTIONS:out.append('<details class="interview" open><summary>'+E(question)+'</summary><p><strong>Answer:</strong> '+E(answer)+'</p></details>')
    out.append('<p><a href="docs/ARGOCD-COMPONENTS.md">Printable component notes</a>. Official references: '+' · '.join('<a href="'+url+'">'+name+'</a>' for name,url in SOURCES)+'.</p><p class="checkpoint">Continue to step 2: open the Argo CD URL. No extra component configuration is required.</p></section>')
    notes=['# Argo CD components and Services\n','Use this after installing Argo CD in Lab 2. It describes the pinned lab chart, not every possible production configuration.\n','![Component diagram](argocd-components.svg)\n','## Component roles\n']
    for name,workload,role,needed in COMPONENTS:notes.append(f'### {name} ({workload})\n\n{role}\n\n{needed}\n')
    notes.append('## Services observed in the live lab\n\n| Service | Service → pod port | Purpose |\n|---|---|---|')
    for row in SERVICES:notes.append('| '+' | '.join(row)+' |')
    notes.append('\nNo application-controller Service is expected here. Service port 443 is not proof of TLS: server.insecure=true selects HTTP for this lab.\n\n## One Git change, step by step\n')
    notes += [f'{i}. {step}' for i,step in enumerate(FLOW,1)]
    notes.append('\n## Inspect with Bash\n')
    for title,cmd in COMMANDS:notes.append(f'### {title}\n\n```bash\n{cmd}\n```\n')
    notes.append('## Interview questions with answers\n')
    for question,answer in QUESTIONS:notes.append(f'**{question}**\n\n{answer}\n')
    notes.append('## Verification\n\nOn 31 October 2026 the live namespace had four Deployments (server, repo-server, Redis, ApplicationSet), one StatefulSet (application-controller), four Services, and ready Service endpoints. Service ports/selectors and pod target ports matched the table. Dex and notifications were disabled. These were read-only checks; no component outage test or production HA claim is made.\n\n## References\n')
    notes += [f'- [{name}]({url})' for name,url in SOURCES]
    P('docs/ARGOCD-COMPONENTS.md').write_text('\n'.join(notes)+'\n',encoding='utf-8',newline='\n')
    return ''.join(out)
